            Java

    import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

// Thread-safe message queue
class MessageQueue {
    private Queue<String> queue = new LinkedList<>();
    private Lock lock = new ReentrantLock();
    private Condition notEmpty = lock.newCondition();

    public void send(String message) {
        lock.lock();
        try {
            queue.add(message);
            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }

    public String receive() {
        lock.lock();
        try {
            while (queue.isEmpty()) {
                try {
                    notEmpty.await();
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
            return queue.poll();
        } finally {
            lock.unlock();
        }
    }
}

// Producer function
class Producer implements Runnable {
    private MessageQueue mq;
    private int id;
    private String message;

    public Producer(MessageQueue mq, int id, String message) {
        this.mq = mq;
        this.id = id;
        this.message = message;
    }

    @Override
    public void run() {
        System.out.println("Producer " + id + " sending: " + message);
        mq.send(message);
    }
}

// Consumer function
class Consumer implements Runnable {
    private MessageQueue mq;

    public Consumer(MessageQueue mq) {
        this.mq = mq;
    }

    @Override
    public void run() {
        String msg = mq.receive();
        System.out.println("Consumer received: " + msg);
    }
}

public class Main {
    public static void main(String[] args) {
        MessageQueue messageQueue = new MessageQueue();

        Thread producerThread = new Thread(new Producer(messageQueue, 1, "Hello, World!"));
        Thread consumerThread = new Thread(new Consumer(messageQueue));

        producerThread.start();
        consumerThread.start();

        try {
            producerThread.join();
            consumerThread.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}


